'use strict';
const dimensions=['职业机会','居住负担','公共交通','气候舒适','公共服务'];
const dimensionKeys=['职业','住房','交通','气候','公共服务'];
function industryView(){const c=profile(selected());const records=CITIES.filter(x=>x.sectors);const colors=['#c2ce93','#ea9c7b','#7596b8'];return cityStrip()+`<div class="two-column"><article class="panel inner"><div class="kicker">${c.en} / 产业观察</div><h2 class="intro-title">${c.name}的经济底色</h2><p class="intro-text">${esc(c.summary)}</p>${(c.industries||c.industry.map(name=>({name,strength:'城市的重要产业方向。'}))).map((s,i)=>`<div class="sector-card"><h3><span>${String(i+1).padStart(2,'0')}</span>${esc(s.name)}</h3><p>${esc(s.strength)}</p><p class="caption" style="color:#9b7767">关注：${esc(s.tradeoff||'产业竞争、人才与商业化进程')}</p></div>`).join('')}</article><div><section class="panel inner"><div class="kicker">产业结构 / 2024</div><h2>制造与服务，各有分工</h2><p class="caption">三次产业增加值占 GDP 的比例。这里只画已取得可追溯份额的四城，不填补缺失数据。</p><svg class="chart" viewBox="0 0 480 245" role="img" aria-label="四城产业结构：苏州第二产业占46.8%，南京31.5%，广州25.26%，成都28.7%">${records.map((r,i)=>{let x=67;return `<text class="chart-label" x="0" y="${40+i*46}">${r.name}</text>`+r.sectors.map((n,j)=>{let w=n*3.78;let part=`<rect x="${x}" y="${23+i*46}" width="${w}" height="25" rx="${j===2?3:0}" fill="${colors[j]}"><title>${r.name} · ${['第一','第二','第三'][j]}产业 ${n}%</title></rect>`;x+=w;return part;}).join('')+`<text x="447" y="${40+i*46}" text-anchor="end" style="fill:white;font-size:11px">${r.sectors[2]}%</text>`;}).join('')}${['第一产业','第二产业','第三产业'].map((n,i)=>`<rect x="${i*158}" y="225" width="9" height="9" rx="2" fill="${colors[i]}"/><text x="${i*158+17}" y="234">${n}</text>`).join('')}</svg><details class="caption"><summary>查看结构数据与口径</summary><div class="scroll-table"><table class="compare-table"><thead><tr><th>城市</th><th>第一产业</th><th>第二产业</th><th>第三产业</th></tr></thead><tbody>${records.map(r=>`<tr><td>${r.name}</td>${r.sectors.map(s=>`<td>${s}%</td>`).join('')}</tr>`).join('')}</tbody></table></div><p>苏州、南京为公报披露比例；广州、成都按披露的增加值计算并四舍五入。产业方向文字为编辑归纳，不代表各行业占比。</p></details></section><section class="panel inner" style="margin-top:20px"><div class="kicker">规模 × 增速</div><h2>大城市，也有不同速度</h2>${scatter()}<p class="caption">横轴为现价 GDP；纵轴为不变价实际增长。杭州增速尚未核验，未进入散点图；重庆增速为工作报告估计。</p></section></div></div><div class="section-head"><div><h2>十城产业速览</h2><p>选择城市，切换上方产业链分析。</p></div></div><div class="industry-grid">${filtered().map(r=>`<button class="industry-cell" data-city="${r.id}" style="text-align:left"><b>${r.name} <span class="caption">/ ${r.region}</span></b><p>${r.industry.join(' · ')}</p></button>`).join('')||'<p class="empty">没有匹配的城市。</p>'}</div>`;}
function scatter(){const cs=CITIES.filter(c=>typeof c.growth==='number');const x=v=>60+(v-1.6)/4*380,y=v=>198-(v-1.5)/5*155;return `<svg class="chart" viewBox="0 0 480 245" role="img" aria-label="GDP总量与实际增速散点图，可选择城市">${[2,4,6].map(n=>`<line class="grid" x1="60" y1="${y(n)}" x2="446" y2="${y(n)}"/><text x="45" y="${y(n)+4}" text-anchor="end">${n}%</text>`).join('')}<line class="axis" x1="60" y1="206" x2="446" y2="206"/>${[2,3,4,5].map(n=>`<text x="${x(n)}" y="226" text-anchor="middle">${n}</text>`).join('')}<text x="446" y="244" text-anchor="end">GDP / 万亿元</text>${cs.map(r=>`<g data-city="${r.id}" role="button" tabindex="0" class="scatter-dot" aria-label="查看${r.name}"><circle cx="${x(r.gdp/10000)}" cy="${y(r.growth)}" r="${r.id===state.city?7:5}" fill="${r.id===state.city?'#e9785e':'#879bb9'}"/><text x="${x(r.gdp/10000)+9}" y="${y(r.growth)+(r.name==='武汉'?15:-8)}" style="font-size:11px">${r.name}</text><title>${r.name}：${fmt(r.gdp/10000)} 万亿元 / ${r.growth}%${r.id==='chongqing'?'（估计）':''}</title></g>`).join('')}</svg>`;}
function livingScore(c){const sum=state.weights.reduce((a,b)=>a+b,0);return sum?c.scores.reduce((s,n,i)=>s+n/5*state.weights[i],0)/sum*100:null;}
function radar(c){const cx=190,cy=164,r=112;const point=(i,value)=>[cx+Math.sin(i*Math.PI*2/5)*r*value,cy-Math.cos(i*Math.PI*2/5)*r*value];return `<svg class="chart" viewBox="0 0 380 322" role="img" aria-label="${c.name}五项编辑参考档位：${dimensions.map((d,i)=>d+c.scores[i]+'/5').join('，')}">${[.2,.4,.6,.8,1].map(n=>`<polygon points="${dimensions.map((d,i)=>point(i,n).join(',')).join(' ')}" fill="none" stroke="#e0e6ee"/>`).join('')}${dimensions.map((d,i)=>{const pt=point(i,1),txt=point(i,1.25);return `<line x1="${cx}" y1="${cy}" x2="${pt[0]}" y2="${pt[1]}" stroke="#e0e6ee"/><text class="chart-label" x="${txt[0]}" y="${txt[1]+4}" text-anchor="middle" style="font-size:12px">${d}</text>`;}).join('')}<polygon points="${c.scores.map((n,i)=>point(i,n/5).join(',')).join(' ')}" fill="#e9785e24" stroke="#e9785e" stroke-width="2"/>${c.scores.map((n,i)=>{const p=point(i,n/5);return `<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#e9785e"><title>${dimensions[i]}：${n}/5</title></circle>`;}).join('')}</svg>`;}
function livingView(){const c=profile(selected()),sum=state.weights.reduce((a,b)=>a+b,0),ranked=[...filtered()].sort((a,b)=>(livingScore(b)||0)-(livingScore(a)||0));return `<div class="info-note">这是偏好实验，不是官方宜居榜。五项参考档位由编辑按城市普遍特征设为 1—5 档，缺少同口径实测指标，且城市内部差异很大；分数仅帮助表达取舍，不代表实际租金、空气质量或个人体验。档位越高，越有利于该项偏好。</div><div class="two-column"><section class="panel inner"><div class="kicker">你的偏好</div><h2>把权重，交给自己</h2><p class="caption">每项 0—100。自动按总权重归一化，五项可以同时调整。</p><div class="preset-buttons"><button data-preset="career">职业优先</button><button data-preset="family">家庭生活</button><button data-preset="budget">居住预算</button><button data-preset="balanced">均衡考虑</button></div><div class="weights">${dimensions.map((d,i)=>`<div class="weight-row"><label for="weight-${i}">${d}<span id="weight-value-${i}">${sum?Math.round(state.weights[i]/sum*100):0}%</span></label><input type="range" id="weight-${i}" data-weight="${i}" min="0" max="100" value="${state.weights[i]}" aria-label="${d}权重"><small>${['岗位与产业匹配的机会广度','越高表示一般居住负担相对轻；未使用租金统计','以轨道与主要城区出行为参考','按一般体感归纳，个人对湿热与寒冷的偏好不同','资源供给广度，个人使用资格需要另行核对'][i]}</small></div>`).join('')}</div><button class="secondary" data-preset="balanced">恢复均衡权重</button></section><section class="panel inner"><div class="kicker">偏好匹配 / 示例模型</div><h2>你的选择，会改变顺序</h2><div id="living-rank">${livingResults(ranked,sum)}</div></section></div><div class="section-head"><div><h2>生活到${c.name}，意味着什么</h2><p>参考档位与真实生活的取舍一起看。</p></div></div>${cityStrip()}<section class="panel inner"><div class="two-column"><div>${radar(c)}</div><div><h2>${c.name} / 日常生活</h2><p class="intro-text">${esc(c.summary)}</p><div class="chip-row">${(c.fits||[]).map(f=>`<span class="chip">${esc(f)}</span>`).join('')}</div><p class="caption" style="margin-top:20px">雷达图为编辑示意；1 是相对弱项，5 是相对优势。居住负担仅比较普遍压力，未使用你的收入及片区房租。</p></div></div><div class="dimension-grid">${dimensions.map((d,i)=>`<div class="dimension"><b>${d}</b><div class="grade">${c.scores[i]}<span class="caption"> / 5</span></div><p>${esc(c.living?.[i]||'请按具体工作和居住片区核对。')}</p></div>`).join('')}</div>${(c.livability||[]).map(l=>`<div class="sector-card"><h3>${esc(l.dimension)}</h3><p>${esc(l.strength)}</p><p>取舍：${esc(l.tradeoff)}</p><p class="caption" style="color:#638078">实地核对：${esc(l.check)}</p></div>`).join('')}</section>`;}
function livingResults(ranked,sum){if(!sum)return '<p class="empty">所有权重均为 0。提高任意一项权重，即可查看偏好匹配。</p>';if(!ranked.length)return '<p class="empty">没有匹配的城市。请调整筛选。</p>';return ranked.map((r,i)=>`<div class="living-result"><span>${String(i+1).padStart(2,'0')}</span><div><button data-city="${r.id}">${r.name}</button><p>${r.tag}</p></div><strong>${Math.round(livingScore(r))}<span style="font-size:11px;color:#a4aebb"> /100</span></strong></div>`).join('')+'<p class="caption" style="margin-top:18px">匹配分 = Σ（归一化权重 × 档位 ÷ 5）× 100。结果是偏好示例，同分不代表城市相同。</p>';}
window.applyPreset=function(type){state.weights=({career:[60,10,10,5,15],family:[10,25,20,15,30],budget:[10,60,15,5,10],balanced:[20,20,20,20,20]})[type]||[20,20,20,20,20];render();};
function historyView(){const c=profile(selected());return cityStrip()+`<section class="panel inner"><div class="kicker">${c.en} / 时间的层次</div><h2 class="intro-title">${c.name}，如何成为今天的${c.name}</h2><p class="intro-text">${esc(c.tagline||c.summary)}</p><div class="timeline">${(c.history||[]).map(e=>`<article class="event"><div class="year">${esc(e.displayYear||e.year)}</div><div class="node"></div><h3>${esc(e.title)}</h3><p>${esc(e.detail||e.text)}</p></article>`).join('')}</div><p class="caption">节点是城市演变的选读，并非完整历史；古代建城、设县和现代行政设立属于不同概念。</p></section><div class="section-head"><div><h2>十城的不同起点</h2><p>贸易、都城、工业与改革，共同塑造今天的城市网络。</p></div></div><section class="panel inner">${filtered().map(r=>{const p=profile(r);return `<article class="history-city"><div><h3><button class="text-btn" data-city="${r.id}" style="font-size:21px;color:var(--ink);padding:0">${r.name}</button></h3><div class="city-en">${r.en}</div></div><p>${esc(p.tagline||p.summary)}<br><span class="caption">${(p.history||[]).map(h=>(h.displayYear||h.year)+' '+h.title).join(' → ')}</span></p></article>`;}).join('')}</section>`;}
function futureChart(){const x=t=>56+t/10*505;const y=v=>252-(v-90)/135*213;const rates=[2,4.5,7];let paths=rates.map((rate,i)=>{const d=Array.from({length:11},(_,t)=>[x(t),y(100*Math.pow(1+rate/100,t))]);return `<polyline points="${d.map(v=>v.join(',')).join(' ')}" fill="none" stroke="${['#9eaec2','#e77b61','#67ac9f'][i]}" stroke-width="${state.rate===rate?3:1.6}" stroke-dasharray="${state.rate===rate?'none':'5 5'}"/>`;}).join('');const p=Array.from({length:11},(_,t)=>[x(t),y(100*Math.pow(1+state.rate/100,t))]);const v=100*Math.pow(1+state.rate/100,state.year-2026),cx=x(state.year-2026),cy=y(v);return `<svg class="chart" viewBox="0 0 620 295" role="img" aria-label="2026至2036年经济规模情景指数，基准100，当前名义年增长假设${state.rate}%，${state.year}年指数${v.toFixed(1)}">${[100,150,200].map(n=>`<line class="grid" x1="56" y1="${y(n)}" x2="561" y2="${y(n)}"/><text x="44" y="${y(n)+4}" text-anchor="end">${n}</text>`).join('')}${paths}<polyline points="${p.map(v=>v.join(',')).join(' ')}" fill="none" stroke="#e77b61" stroke-width="3"/><line x1="${cx}" y1="30" x2="${cx}" y2="252" stroke="#c4cdda" stroke-dasharray="4 4"/><circle cx="${cx}" cy="${cy}" r="5" fill="#e77b61"/><text class="chart-label" x="${Math.min(cx,528)}" y="${cy-13}" text-anchor="middle">${v.toFixed(1)}</text>${[2026,2028,2030,2032,2034,2036].map(t=>`<text x="${x(t-2026)}" y="281" text-anchor="middle">${t}</text>`).join('')}<text x="56" y="16" style="font-size:11px">经济规模指数 / 2026 = 100</text></svg>`;}
function futureView(){const c=profile(selected()),o=c.outlook||{baseline:c.summary,catalysts:c.catalysts,risks:c.risks,watchMetrics:c.watch},val=100*Math.pow(1+state.rate/100,state.year-2026);return cityStrip()+`<div class="two-column"><section class="panel inner"><div class="kicker">2026—2036 / 条件性展望</div><h2 class="intro-title">${c.name}的下一段路</h2><p class="intro-text">${esc(o.baseline)}</p><h3 style="margin-top:27px">可能的增长驱动力</h3><ul class="future-list">${(o.catalysts||[]).map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h3 style="margin-top:27px">可能改变路径的风险</h3><ul class="future-list">${(o.risks||[]).map(t=>`<li>${esc(t)}</li>`).join('')}</ul><h3 style="margin-top:27px">未来值得持续观察</h3><div class="chip-row">${(o.watchMetrics||[]).map(t=>`<span class="chip">${esc(t)}</span>`).join('')}</div><p class="caption" style="margin-top:20px">以上是产业与城市条件的编辑分析，不是概率预测。</p></section><section class="panel inner"><div class="kicker">情景沙盘 / 复利演算</div><h2>如果增长速度改变</h2><p class="caption">以假设的 2026 年规模为 100。三条路径仅演示名义增长率对规模的影响；没有估计任何城市的 2026 年实际 GDP。</p><div class="segmented" style="margin:18px 0" aria-label="选择情景">${[['low','审慎 · 2%'],['base','中性 · 4.5%'],['high','积极 · 7%']].map(([s,n])=>`<button data-scenario="${s}" class="${state.scenario===s?'selected':''}" aria-pressed="${state.scenario===s}">${n}</button>`).join('')}</div><div id="future-chart">${futureChart()}</div><div class="forecast-metric"><div><b id="forecast-value">${val.toFixed(1)}</b><small id="forecast-year">${state.year} 年指数</small></div><div><b id="forecast-rate" style="color:var(--accent)">${state.rate.toFixed(1)}%</b><small>每年名义增长假设</small></div></div><label for="forecast-growth" class="caption">调整年度增长率（0%—8%）</label><input id="forecast-growth" class="forecast-range" type="range" min="0" max="8" step="0.1" value="${state.rate}" style="margin:12px 0 22px"><label for="forecast-time" class="caption" id="forecast-time-label">观察年份：${state.year}</label><input id="forecast-time" class="forecast-range" type="range" min="2026" max="2036" step="1" value="${state.year}" style="margin:12px 0"><div class="info-note">指数 = 100 × (1 + 年增长假设) ^ 年数。所有城市使用相同的演算规则；不从 2024 年实际增速外推，也不预测未来排名。名义增长包含价格因素，实际生活水平还取决于就业、收入与物价。</div></section></div>`;}
function sourceView(){return `<section class="panel source-card"><div class="kicker">版本与范围</div><h2>2024 年度十城对照，非当前最新排名</h2><p>本网站覆盖中国大陆 2024 年 GDP 前十的上海、北京、深圳、重庆、广州、苏州、成都、杭州、武汉、南京。统一比较行政市域，包含所辖区县或县级市；不等同于都市圈或连续建成区。资料整理日期：2026 年 10 月 3 日。</p><p>2025 年度统计已经发布，但本版本尚未取得完整、可交叉核验的十城资料，所以继续使用 2024 年基准。GDP 按现价计量，实际增速按不变价格计量，初步核算数也可能在年鉴或经济普查后修订。地图只用于地理定位，不能作为边界审定依据。</p></section><section class="panel source-card"><h2>信息类型与分析边界</h2><div class="industry-grid"><div class="industry-cell"><b>统计事实</b><p>2024 年 GDP、已取得证据的实际增速与四城三次产业结构。逐城证据类型见下表。</p></div><div class="industry-cell"><b>编辑性分析</b><p>主导产业归纳、生活取舍、历史节点选读与未来驱动力。宜居的 1—5 档是示例判断，不是官方测量。</p></div><div class="industry-cell"><b>偏好实验</b><p>你的权重决定匹配顺序。档位缺少同口径实测数据，仅适合探索问题，不适合当作定居决策依据。</p></div><div class="industry-cell"><b>情景假设</b><p>2026—2036 年规模指数是恒定名义增长率的复利演算，不是对 GDP 或未来排名的预测。</p></div></div></section><section class="panel source-card"><h2>逐城证据与数字</h2><p>本次未直接读取统计局原站，采用公开存档与引用官方发布的新闻镜像。点击“证据”可读取实际使用的资料；官方参考链接用于后续核对，不代表本次已在原站验证。</p><div class="scroll-table"><table class="compare-table"><thead><tr><th>城市</th><th>GDP / 亿元</th><th>实际增长</th><th>证据等级与限制</th><th>来源</th></tr></thead><tbody>${CITIES.map(c=>`<tr><td>${c.name}</td><td>${fmt(c.gdp,c.gdp===26727?1:c.gdp===21860?0:2)}</td><td>${typeof c.growth==='number'?c.growth.toFixed(1)+'%'+(c.id==='chongqing'?'（估计）':''):'待核验'}</td><td style="min-width:210px">${esc(c.evidenceNote)}</td><td><a href="${esc(c.sourceUrl)}" target="_blank" rel="noopener noreferrer">证据存档</a>${c.officialUrl&&c.id!=='hangzhou'?`<br><a href="${esc(c.officialUrl)}" target="_blank" rel="noopener noreferrer">官方参考</a>`:''}</td></tr>`).join('')}</tbody></table></div><p class="caption">重庆精确总量来自教学聚合资料，5.7% 为工作报告估计；杭州 GDP 来自引用公报的二手笔记，精度取整，其实际增速留空。这两城总量仅供暂定对照，十城合计也继承上述限制。</p></section><section class="panel source-card"><h2>城市切面：案例与使用边界</h2><p>医疗、交通、文化、教育科研与公园休闲共五个切面，以代表机构、设施和地方资源为例，展示分布、日常取舍与实地核对问题。每城每个切面选三个案例，仅为编辑选读，不是完整名录或强弱排名。</p><p>切面内容整理于2026年10月3日，属于稳定事实与编辑分析，未逐项进行实时来源核验。政府、机构和运营主体官网链接均为参考入口；医院院区、门诊安排、交通班次、场馆开放、大学参观与入学规则均需核对当前说明。未用GDP推算公共资源强弱，也未填入未经核验的设施数量或评分。</p></section><section class="panel source-card"><h2>历史、地图与进一步核对</h2><p>每城手绘地图为AI生成的概念示意图，并叠加编辑选取的地标标签；道路、边界、建筑位置与距离经过简化，不是精确地理数据或导航地图。图中的文字、地标说明和切面入口为可交互页面内容。</p><p>历史节点为稳定事实的编辑选读，未逐条在本次核验。上海设县采用 1292 年（批准设县与正式建置在部分叙述中存在时间口径差异）；深圳证券交易所节点指 1990 年试营业，不是 1991 年正式成立。涉及求职、住房、入学或医疗时，请核对具体片区与当前政策。</p><div class="source-links"><a href="https://raw.githubusercontent.com/apache/echarts/4.9.0/map/json/china.json" target="_blank" rel="noopener noreferrer">地图：Apache ECharts 4.9.0<small>Apache-2.0 · 本页仅显示大陆省级轮廓，供位置示意</small></a><a href="https://www.stats.gov.cn/" target="_blank" rel="noopener noreferrer">国家统计局<small>核对统计制度、年度核算与修订口径</small></a></div><p class="caption">地图数据已解码、闭合多边形并移除零面积线段。<a href="echarts-LICENSE.txt">许可证</a> · <a href="echarts-NOTICE.txt">版权说明</a> · <a href="research-data.json">本版研究资料</a></p></section>`;}
window.renderExtra=function(v){return ({facets:window.facetsView||(()=>''),industry:industryView,living:livingView,history:historyView,future:futureView,sources:sourceView})[v]();};
document.addEventListener('input',e=>{if(e.target.dataset.weight!==undefined){state.weights[Number(e.target.dataset.weight)]=Number(e.target.value);const sum=state.weights.reduce((a,b)=>a+b,0);state.weights.forEach((v,i)=>$('#weight-value-'+i).textContent=(sum?Math.round(v/sum*100):0)+'%');$('#living-rank').innerHTML=livingResults([...filtered()].sort((a,b)=>(livingScore(b)||0)-(livingScore(a)||0)),sum);}if(e.target.id==='forecast-growth'||e.target.id==='forecast-time'){if(e.target.id==='forecast-growth'){state.rate=Number(e.target.value);state.scenario=Object.entries({low:2,base:4.5,high:7}).find(([k,v])=>v===state.rate)?.[0]||'custom';document.querySelectorAll('[data-scenario]').forEach(n=>{n.classList.toggle('selected',n.dataset.scenario===state.scenario);n.setAttribute('aria-pressed',n.dataset.scenario===state.scenario);});}else state.year=Number(e.target.value);$('#future-chart').innerHTML=futureChart();$('#forecast-value').textContent=(100*Math.pow(1+state.rate/100,state.year-2026)).toFixed(1);$('#forecast-year').textContent=state.year+' 年指数';$('#forecast-rate').textContent=state.rate.toFixed(1)+'%';$('#forecast-time-label').textContent='观察年份：'+state.year;}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('.scatter-dot')){e.preventDefault();setCity(e.target.dataset.city);}});
function registerWebMCP(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const spec=[{name:'read_city_atlas',description:'读取当前城市、视角和2024年经济数据，注明数据限制。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({view:state.view,city:selected().name,vintage:2024,gdp:selected().gdp,realGrowth:selected().growth,evidence:selected().evidenceNote,comparison:state.compare})},{name:'navigate_city_atlas',description:'在城市图鉴中选择城市和探索视角，更新可见页面。',inputSchema:{type:'object',properties:{city:{type:'string',enum:CITIES.map(c=>c.id)},view:{type:'string',enum:Object.keys(views)}},required:['city','view'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!CITIES.some(c=>c.id===input.city)||!views[input.view])throw new Error('无效的城市或视角');state.city=input.city;setView(input.view);return{city:selected().name,view:state.view};}},{name:'configure_city_comparison',description:'选择最多四座城市进行比较，并打开城市总览。',inputSchema:{type:'object',properties:{cities:{type:'array',items:{type:'string',enum:CITIES.map(c=>c.id)},minItems:1,maxItems:4,uniqueItems:true}},required:['cities'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!Array.isArray(input.cities)||input.cities.length<1||input.cities.length>4||new Set(input.cities).size!==input.cities.length||input.cities.some(id=>!CITIES.some(c=>c.id===id)))throw new Error('请提供1—4个不重复的有效城市');state.compare=[...input.cities];setView('overview');return{cities:state.compare.map(id=>CITIES.find(c=>c.id===id).name)};}}];for(const t of spec){try{Promise.resolve(ctx.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}registerWebMCP();render();
